static inline bool w_str_eq(w_string a, w_string b) { return a.len == b.len && (a.len == 0 || memcmp(a.str, b.str, a.len) == 0); }
static inline int w_str_cmp(w_string a, w_string b) { uint32_t n = a.len < b.len ? a.len : b.len; int r = n ? memcmp(a.str, b.str, n) : 0; return r ? r : (a.len < b.len ? -1 : a.len > b.len); }
static inline w_string w_str_cat(w_string a, w_string b) { uint32_t n = a.len + b.len; uint8_t* p = (uint8_t*)malloc(n + 1); if (a.len) memcpy(p, a.str, a.len); if (b.len) memcpy(p + a.len, b.str, b.len); p[n] = 0; return (w_string){ .str = p, .len = n }; }
static inline bool w_cmp_lt_iu(int64_t a, uint64_t b) { return a < 0 ? true  : (uint64_t)a <  b; }
static inline bool w_cmp_le_iu(int64_t a, uint64_t b) { return a < 0 ? true  : (uint64_t)a <= b; }
static inline bool w_cmp_gt_iu(int64_t a, uint64_t b) { return a < 0 ? false : (uint64_t)a >  b; }
static inline bool w_cmp_ge_iu(int64_t a, uint64_t b) { return a < 0 ? false : (uint64_t)a >= b; }
static inline bool w_cmp_eq_iu(int64_t a, uint64_t b) { return a < 0 ? false : (uint64_t)a == b; }
static inline bool w_cmp_ne_iu(int64_t a, uint64_t b) { return a < 0 ? true  : (uint64_t)a != b; }
static inline void* w_array_at(w_array a, int64_t i) { if (i < 0 || i >= a.len) { fprintf(stderr, "--- W panic ---\narray index %lld out of range 0..%lld\n", (long long)i, (long long)a.len); exit(1); } return (uint8_t*)a.data + i * a.elem_size; }
static void w_array_oob(int64_t i, int64_t len) { fprintf(stderr, "--- W panic ---\narray index %lld out of range 0..%lld\n", (long long)i, (long long)len); exit(1); }

